package com.chahinaz.pos;
import java.io.ByteArrayInputStream;import java.math.BigDecimal;import java.sql.Timestamp;import java.time.Instant;import java.util.UUID;import org.apache.poi.ss.usermodel.CellType;import org.apache.poi.xssf.usermodel.XSSFWorkbook;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.*;import org.springframework.test.web.servlet.MockMvc;import org.testcontainers.junit.jupiter.*;import org.testcontainers.postgresql.PostgreSQLContainer;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.user;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@Testcontainers @SpringBootTest(properties={"POS_BOOTSTRAP_ADMIN_USERNAME=bootstrap","POS_BOOTSTRAP_ADMIN_PASSWORD=development-test-password-only","pos.store-timezone=Asia/Beirut"}) @AutoConfigureMockMvc
class Phase5PostgresIntegrationTest {
 @Container static PostgreSQLContainer postgres=new PostgreSQLContainer("postgres:16-alpine");@DynamicPropertySource static void db(DynamicPropertyRegistry p){p.add("spring.datasource.url",postgres::getJdbcUrl);p.add("spring.datasource.username",postgres::getUsername);p.add("spring.datasource.password",postgres::getPassword);}@Autowired MockMvc mvc;@Autowired JdbcTemplate db;
 record Seed(UUID sale,UUID product){}
 @BeforeEach void clean(){db.execute("truncate table payment,sale_return_item,sale_return,inventory_movement,sale_item,sale,register_session,manager_approval,product,category cascade");}
 Seed seed(){UUID employee=db.queryForObject("select id from employee where username='bootstrap'",UUID.class),category=UUID.randomUUID(),product=UUID.randomUUID(),sale=UUID.randomUUID(),item=UUID.randomUUID(),ret=UUID.randomUUID();Timestamp now=Timestamp.from(Instant.now());db.update("insert into category(id,name,active,created_at,updated_at) values(?,?,true,?,?)",category,"Original category",now,now);db.update("insert into product(id,sku,name,category_id,cost_price_usd,selling_price_usd,stock_quantity,low_stock_threshold,active,publication_status,featured,new_arrival,created_at,updated_at) values(?,?,?,?,?,?,0,2,true,'DRAFT',false,false,?,?)",product,"P-1","Current product",category,new BigDecimal("99.00"),new BigDecimal("10.00"),now,now);db.update("insert into sale(id,sale_number,employee_id,cashier_name_snapshot,status,subtotal_usd,total_discount_usd,sale_discount_usd,total_usd,exchange_rate,amount_paid_usd,amount_paid_lbp,whish_amount_usd,change_usd,change_lbp,created_at,completed_at) values(?,?,?,?,'COMPLETED',20,2,0,18,89500,10,89500,7,0,0,?,?)",sale,"R-500",employee,"Historical cashier",now,now);db.update("insert into sale_item(id,sale_id,product_id,sku_snapshot,product_name_snapshot,cost_price_usd_snapshot,category_id_snapshot,category_name_snapshot,original_unit_price_usd,effective_unit_price_usd,discount_usd,quantity,line_total_usd) values(?,?,?,?,?,?,?,?,10,10,2,2,18)",item,sale,product,"P-1","=FORMULA",new BigDecimal("3.00"),category,"Original category");db.update("insert into payment(id,sale_id,payment_type,amount_usd,manually_confirmed,created_at) values(?,?,'USD_CASH',10,false,?)",UUID.randomUUID(),sale,now);db.update("insert into payment(id,sale_id,payment_type,amount_lbp,manually_confirmed,created_at) values(?,?,'LBP_CASH',89500,false,?)",UUID.randomUUID(),sale,now);db.update("insert into payment(id,sale_id,payment_type,amount_usd,manually_confirmed,created_at) values(?,?,'WHISH_MANUAL',7,true,?)",UUID.randomUUID(),sale,now);db.update("insert into sale_return(id,original_sale_id,employee_id,refund_usd,refund_lbp,refund_method,whish_manually_recorded,reason,created_at) values(?,?,?,9,0,'USD_CASH',false,'Return',?)",ret,sale,employee,now);db.update("insert into sale_return_item(id,return_id,sale_item_id,quantity,amount_usd,restockable) values(?,?,?,1,9,false)",UUID.randomUUID(),ret,item);UUID held=UUID.randomUUID(),voided=UUID.randomUUID();db.update("insert into sale(id,sale_number,employee_id,cashier_name_snapshot,status,subtotal_usd,total_discount_usd,sale_discount_usd,total_usd,amount_paid_usd,amount_paid_lbp,whish_amount_usd,change_usd,change_lbp,created_at) values(?,?,?,?,'HELD',100,0,0,100,0,0,0,0,0,?)",held,"R-H",employee,"Cashier",now);db.update("insert into sale(id,sale_number,employee_id,cashier_name_snapshot,status,subtotal_usd,total_discount_usd,sale_discount_usd,total_usd,amount_paid_usd,amount_paid_lbp,whish_amount_usd,change_usd,change_lbp,created_at,voided_at,void_reason,voided_by) values(?,?,?,?,'VOIDED',100,0,0,100,0,0,0,0,0,?,?,?,?)",voided,"R-V",employee,"Cashier",now,now,"Cancelled",employee);return new Seed(sale,product);}
 @Test void dashboardProfitPaymentsAndSnapshotsAreAccurate()throws Exception{seed();mvc.perform(get("/api/management/reports/dashboard").with(user("bootstrap").roles("ADMIN"))).andExpect(status().isOk()).andExpect(jsonPath("$.grossSales").value(20.0)).andExpect(jsonPath("$.netSales").value(18.0)).andExpect(jsonPath("$.completedTransactions").value(1)).andExpect(jsonPath("$.unitsSold").value(2)).andExpect(jsonPath("$.totalDiscounts").value(2.0)).andExpect(jsonPath("$.totalRefunds").value(9.0)).andExpect(jsonPath("$.netRevenueAfterRefunds").value(9.0)).andExpect(jsonPath("$.costOfGoodsSold").value(3.0)).andExpect(jsonPath("$.grossProfit").value(6.0)).andExpect(jsonPath("$.voidedSales").value(1)).andExpect(jsonPath("$.heldSales").value(1));mvc.perform(get("/api/management/reports/payments").with(user("bootstrap").roles("ADMIN"))).andExpect(jsonPath("$.usdCash").value(10.0)).andExpect(jsonPath("$.lbpCash").value(89500)).andExpect(jsonPath("$.whishUsd").value(7.0)).andExpect(jsonPath("$.mixedSales").value(1));mvc.perform(get("/api/management/reports/products").with(user("bootstrap").roles("MANAGER"))).andExpect(status().isOk()).andExpect(jsonPath("$[0].productName").value("=FORMULA")).andExpect(jsonPath("$[0].costOfGoodsSold").value(3.0)).andExpect(jsonPath("$[0].grossProfit").value(6.0)).andExpect(jsonPath("$[0].quantityReturned").value(1));mvc.perform(get("/api/management/reports/categories").with(user("bootstrap").roles("ADMIN"))).andExpect(jsonPath("$[0].categoryName").value("Original category"));}
 @Test void securityRangesAndStablePaginationAreEnforced()throws Exception{seed();mvc.perform(get("/api/management/reports/dashboard").with(user("teller").roles("TELLER"))).andExpect(status().isForbidden());mvc.perform(get("/api/management/reports/dashboard?from=2026-09-20&to=2026-09-19").with(user("bootstrap").roles("ADMIN"))).andExpect(status().isBadRequest());mvc.perform(get("/api/pos/sales?page=0&size=10").with(user("bootstrap").roles("ADMIN"))).andExpect(status().isOk()).andExpect(jsonPath("$.content").isArray()).andExpect(jsonPath("$.page").value(0)).andExpect(jsonPath("$.size").value(10)).andExpect(jsonPath("$.totalElements").value(3)).andExpect(jsonPath("$.pageable").doesNotExist());}
 @Test void inventoryAndXlsxUseNumericCellsAndNeutralizeFormulas()throws Exception{seed();mvc.perform(get("/api/management/reports/inventory?stockStatus=out").with(user("bootstrap").roles("ADMIN"))).andExpect(status().isOk()).andExpect(jsonPath("$[0].inventoryValue").value(0)).andExpect(jsonPath("$[0].nonRestockableReturns").value(1));byte[] bytes=mvc.perform(get("/api/management/reports/exports/products").with(user("bootstrap").roles("ADMIN"))).andExpect(status().isOk()).andExpect(header().string("Content-Type","application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")).andReturn().getResponse().getContentAsByteArray();try(XSSFWorkbook wb=new XSSFWorkbook(new ByteArrayInputStream(bytes))){var sheet=wb.getSheet("Report");assertEquals("'=FORMULA",sheet.getRow(5).getCell(1).getStringCellValue());assertEquals(CellType.NUMERIC,sheet.getRow(5).getCell(2).getCellType());}}
}

